#include <stdio.h>

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int v[505];
    for (int i = 0; i < N; i++) {
        scanf("%d", &v[i]);
    }

    int ans = (N > 0) ? 1 : 0;

    for (int a = 1; a <= N; a++) {
        for (int b = a + 1; b <= N; b++) {
            int last = 0;
            int cnt = 0;

            for (int i = 0; i < N; i++) {
                if (v[i] == a) {
                    if (last != 1) {
                        cnt++;
                        last = 1;
                    }
                } else if (v[i] == b) {
                    if (last != 2) {
                        cnt++;
                        last = 2;
                    }
                }
            }

            if (cnt > ans) ans = cnt;
        }
    }

    printf("%d\n", ans);
    return 0;
}
